def factorial(n):
    """
    Compute the factorial of a non-negative integer.

    Args:
        n (int): Input number

    Returns:
        int: Factorial of n
    """
    if n < 0:
        raise ValueError("Factorial is not defined for negative numbers")
    elif n == 0 or n == 1:
        return 1
    else:
        return n * factorial(n-1)
```

